using System;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckTornadoRodeo.Editor {
 public static class TornadoPresentationAuthoring {
  const string Shared="Assets/TruckSports/Settings/Keepaway broadcast framing.asset";
  public static void InstallSavedReadablePresentation(){if(EditorApplication.isPlaying||EditorApplication.isCompiling)throw new InvalidOperationException("Stopped compiled Editor required.");for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)if(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty)throw new InvalidOperationException("Preserve dirty scene before explicit Tornado presentation repair.");var scene=EditorSceneManager.OpenScene(TornadoAuthoring.ScenePath,OpenSceneMode.Single);InstallOpenReadablePresentation();if(!EditorSceneManager.SaveScene(scene))throw new System.IO.IOException("Could not save owned Tornado presentation repair.");}
  public static void InstallOpenReadablePresentation(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlaying||EditorApplication.isCompiling||scene.path!=TornadoAuthoring.ScenePath)throw new InvalidOperationException("Exact stopped owned Tornado scene required.");var m=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<TornadoMatch>(true)).Single();var frame=m.broadcast.GetComponent<SportsBroadcastFraming>();if(frame==null||frame.session!=m||frame.cameraRig!=m.broadcast||frame.trucks.Length!=4||!frame.trucks.SequenceEqual(m.trucks)||frame.sharedDefaults==null||AssetDatabase.GetAssetPath(frame.sharedDefaults)!=Shared)throw new InvalidOperationException("Exact original four-truck common Cinemachine binding required; preserve custom scene.");var expected=JsonUtility.FromJson<SportsBroadcastSettings>(JsonUtility.ToJson(frame.sharedDefaults.settings));expected.elevation=35;expected.azimuth=-35;expected.minimumTruckHeight=.10f;expected.preferredTruckHeight=.13f;expected.maximumDistanceInTruckLengths=9;expected.nearbyTruckLengths=3;expected.primaryWeight=4;expected.objectiveWeight=1;expected.minimumShotSeconds=2.2f;expected.groupFramingSize=.76f;if(!frame.useSharedDefaults&&JsonUtility.ToJson(frame.settings)!=JsonUtility.ToJson(expected))throw new InvalidOperationException("Preserve custom Tornado per-sport camera settings.");var presenters=m.menus.GetComponentsInChildren<SportsScorePresentation>(true).Where(p=>p.session==m).ToArray();if(presenters.Length!=1)throw new InvalidOperationException("Exactly one owned Heat receipt presenter required.");var presenter=presenters[0];var notification=presenter.notification;var accent=presenter.accent;if(notification==null||accent==null||presenter.name!="Rodeo confirmed stunts · existing Heat"||accent.name!="Actual credited participant color"||accent.raycastTarget||accent.sprite!=null)throw new InvalidOperationException("Preserve custom notification bindings.");var mask=notification.transform.Find("Mask Content")as RectTransform;var rect=accent.rectTransform;if(mask==null||mask.GetComponent<CanvasGroup>()==null||rect.parent!=notification.transform&&rect.parent!=mask||rect.anchorMin!=Vector2.zero||rect.anchorMax!=new Vector2(1,0)||rect.offsetMin!=new Vector2(10,2)||rect.offsetMax!=new Vector2(-10,6)||rect.localScale!=Vector3.one||Quaternion.Angle(rect.localRotation,Quaternion.identity)>.001f)throw new InvalidOperationException("Preserve customized accent parent/rectangle; expected original owned stripe only.");
   // Preflight both independent repairs before either mutation. The mask
   // already animates the identical stretched parent rectangle through Heat.
   if(rect.parent!=mask){rect.SetParent(mask,false);rect.anchorMin=Vector2.zero;rect.anchorMax=new Vector2(1,0);rect.offsetMin=new Vector2(10,2);rect.offsetMax=new Vector2(-10,6);EditorUtility.SetDirty(rect);}frame.settings=expected;frame.useSharedDefaults=false;EditorUtility.SetDirty(frame);EditorSceneManager.MarkSceneDirty(scene);Debug.Log("TORNADO_READABLE_PRESENTATION_AUTHORED owned35degree/-35azimuth Cinemachine config; actual-ring center objective; original Heat Mask Content owns accent fade. Forces/rings/scoring/shared profile unchanged. Native/visual acceptance pending.");
  }
 }
